window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[152]={"id":"152","numero":152,"titre":"Endocardite infectieuse","objectifs":[{"id":"152-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'une endocardite infectieuse (EI)","contenu":"<p>L'<strong><span class=\"kw-def\">endocardite infectieuse</span></strong> (EI) est une <span class=\"kw-def\">infection de l'endocarde</span>, touchant le plus souvent une ou plusieurs <strong>valves cardiaques natives</strong>, mais pouvant aussi intéresser l'<span class=\"kw-def\">endocarde pariétal</span> ou tout <strong>matériel intracardiaque implanté</strong> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Prothèses valvulaires</span> ;</li>\n        <li><span class=\"kw-etio\">Sondes de stimulateur</span> ou de <span class=\"kw-etio\">défibrillateur</span> ;</li>\n        <li><span class=\"kw-etio\">Assistances ventriculaires</span> ;</li>\n        <li><span class=\"kw-etio\">Cathéter veineux central</span>.</li>\n      </ul>\n      <p><span class=\"kw-clinique\">Les</span> valves du <strong>cœur gauche</strong> (<span class=\"kw-def\">mitrale</span>, <span class=\"kw-def\">aortique</span>) sont <span class=\"kw-alerte\">plus souvent touchées</span> que celles du cœur droit.</p>\n      <div class=\"callout callout-info\"><strong>À distinguer.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">endocardites non infectieuses</span>, beaucoup plus rares, peuvent compliquer un <span class=\"kw-etio\">cancer</span> (endocardites <span class=\"kw-def\">marastiques</span>) ou une <span class=\"kw-etio\">maladie auto-immune</span> — <span class=\"kw-etio\">lupus</span> (lésions de <span class=\"kw-def\">Libman-Sacks</span>), <span class=\"kw-etio\">SAPL</span>.</div>","frequence":0},{"id":"152-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie de l'EI","contenu":"<p>L'<span class=\"kw-bio\">incidence</span> de l'EI <span class=\"kw-alerte\">n'a pas diminué</span> ces dernières décennies, mais le <strong>profil des patients</strong> et la répartition des micro-organismes se sont modifiés : <span class=\"kw-etio\">vieillissement de la population</span>, progrès médicaux, <span class=\"kw-etio\">régression des valvulopathies post-rhumatismales</span>.</p>\n      <p><span class=\"kw-clinique\">Les</span> patients atteints sont désormais plus âgés et/ou exposés par d'autres situations :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Valvulopathies dégénératives</span> — fibrose, prolapsus mitral ;</li>\n        <li><span class=\"kw-etio\">Toxicomanie intraveineuse</span> ;</li>\n        <li><span class=\"kw-etio\">Procédures de soins à risque</span> — circulation extracorporelle, cathéters veineux, hémodialyse, stimulateur/<span class=\"kw-ttt\">défibrillateur</span>, chambre implantable.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Bascule microbiologique.</strong> Autrefois <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">streptocoques oraux</span> étaient majoritaires ; aujourd'hui le premier germe est le <span class=\"kw-etio\">staphylocoque</span>.</div>\n      <table >\n        <thead><tr><th>Donnée</th><th>Repère EDN</th></tr></thead>\n        <tbody>\n          <tr><td>Sex-ratio</td><td>Prédominance <strong>masculine</strong></td></tr>\n          <tr><td>Âge</td><td>Âge moyen <span class=\"kw-chiffre\">62 ans</span> ; plus fréquente après <span class=\"kw-chiffre\">70 ans</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span> hospitalière</td><td><span class=\"kw-alerte\">15-30 %</span><br>1ʳᵉ cause de décès : <span class=\"kw-etio\">insuffisance cardiaque</span><br>2ᵉ cause : <span class=\"kw-alerte\">emboles cérébraux</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Facteurs de mauvais <span class=\"kw-def\">pronostic</span></strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Insuffisance cardiaque aiguë</span>, <span class=\"kw-clinique\">complications neurologiques</span>, <span class=\"kw-alerte\">syndrome infectieux mal maîtrisé</span>, <span class=\"kw-imagerie\">abcès intracardiaques</span>, <span class=\"kw-imagerie\">végétations volumineuses</span> ;</li>\n        <li>EI sur <strong>prothèse</strong> ;</li>\n        <li>Micro-organismes très virulents — <span class=\"kw-etio\">Staphylococcus aureus</span> et <span class=\"kw-etio\">champignons</span> ;</li>\n        <li><span class=\"kw-def\">Terrain</span> fragile — <span class=\"kw-etio\">âge avancé</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">immunodépression</span>, insuffisances cardiaque / rénale / respiratoire.</li>\n      </ul>","frequence":2},{"id":"152-3","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les situations à risque d'EI (cardiopathie du groupe A, présence de matériel intra-cardiaque, bactériémie à cocci Gram positif)","contenu":"<p>Trois grands déterminants exposent à l'EI : une <strong>cardiopathie du groupe A</strong>, la présence de <strong>matériel intra-cardiaque</strong>, et une <strong><span class=\"kw-clinique\">bactériémie</span> à cocci Gram positif</strong>.</p>\n      <p><strong>1 · Cardiopathies du groupe A — haut risque</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">ATCD d'endocardite infectieuse</span> ;</li>\n        <li>Cardiopathies congénitales <span class=\"kw-etio\">cyanogènes non traitées</span> — <span class=\"kw-etio\">tétralogie de Fallot</span>, <span class=\"kw-etio\">transposition des gros vaisseaux</span> ;</li>\n        <li>Cardiopathie <span class=\"kw-etio\">congénitale</span> réparée avec <span class=\"kw-etio\">matériel prothétique</span> — pendant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> suivant la procédure, ou <span class=\"kw-alerte\">à vie</span> s'il existe un <span class=\"kw-alerte\">shunt résiduel</span> ;</li>\n        <li><span class=\"kw-etio\">Prothèses valvulaires</span> (<span class=\"kw-etio\">TAVI</span> inclus) et matériel de réparation valvulaire ;</li>\n        <li>Dispositifs de fermeture, prothèses vasculaires, filtres caves, shunts — durant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 premiers mois</span> après implantation ;</li>\n        <li>Dispositif d'<span class=\"kw-etio\">assistance ventriculaire</span> ; <span class=\"kw-etio\">dérivations chirurgicales</span> pulmonaire-systémique.</li>\n      </ul>\n      <p><strong>2 · Matériel intra-cardiaque</strong> — toute <span class=\"kw-etio\">prothèse valvulaire</span>, <span class=\"kw-etio\">sonde de stimulateur</span> ou de <span class=\"kw-etio\">défibrillateur</span>, <span class=\"kw-etio\">assistance ventriculaire</span> est un corps étranger colonisable.</p>\n      <p><strong>3 · <span class=\"kw-clinique\">Bactériémie</span> à cocci Gram positif</strong> — <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">CG+</span> adhèrent à l'endocarde grâce à des <span class=\"kw-def\">facteurs d'adhésion</span> ; une <span class=\"kw-clinique\">bactériémie</span> ou <span class=\"kw-clinique\">fongémie</span> importante et/ou répétée, partie d'une <span class=\"kw-clinique\">porte d'entrée</span>, peut ensemencer une <span class=\"kw-clinique\">lésion</span> endocardique.</p>\n      <div class=\"callout callout-info\"><strong>Piège classique.</strong> Près de <span class=\"kw-chiffre\">50 %</span> des EI surviennent sur un cœur <strong>sans valvulopathie connue</strong> préexistante — l'absence de cardiopathie connue <span class=\"kw-alerte\">n'élimine jamais le diagnostic</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 233 — Valvulopathie</em></p>","frequence":0},{"id":"152-4","rang":"A","rubrique":"Étiologies","titre":"Connaître les principaux agents infectieux à l'origine d'EI (bactéries, levures)","contenu":"<p>Le micro-organisme en cause est une <span class=\"kw-etio\">bactérie</span> ou, plus rarement, un <span class=\"kw-etio\">champignon</span> (levure). <strong><span class=\"kw-etio\">Staphylocoques</span>, streptocoques et <span class=\"kw-etio\">entérocoques</span></strong> représentent à eux seuls <span class=\"kw-chiffre\">~80 %</span> des EI.</p>\n      <table >\n        <thead><tr><th>Agent <span class=\"kw-etio\">infectieux</span></th><th>Fréquence</th><th>Particularité EDN</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Staphylococcus aureus</span><br>CG+ en amas</td><td><span class=\"kw-chiffre\">30 %</span></td><td><span class=\"kw-alerte\">1ᵉʳ germe</span> ; EI <span class=\"kw-clinique\">les</span> plus graves</td></tr>\n          <tr><td><span class=\"kw-etio\">Streptocoques oraux</span><br>CG+ en chaînette (S. sanguis, mitis, salivarius, mutans)</td><td><span class=\"kw-chiffre\">20 %</span></td><td><span class=\"kw-clinique\">Porte d'entrée</span> <span class=\"kw-clinique\">bucco-dentaire</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Streptocoques du groupe D</span><br>S. gallolyticus (bovis)</td><td><span class=\"kw-chiffre\">13 %</span></td><td>Imposent la recherche d'un <span class=\"kw-alerte\">cancer colique</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Staphylocoques à coagulase négative</span><br>S. epidermidis, S. lugdunensis</td><td><span class=\"kw-chiffre\">10 %</span></td><td>Fréquence <span class=\"kw-alerte\">en augmentation</span>, surtout EI sur prothèse</td></tr>\n          <tr><td><span class=\"kw-etio\">Entérocoques</span><br>E. faecalis, E. faecium</td><td><span class=\"kw-chiffre\">10 %</span></td><td><span class=\"kw-clinique\">Porte d'entrée</span> <span class=\"kw-clinique\">digestive</span> et <span class=\"kw-clinique\">urinaire</span></td></tr>\n          <tr><td>Groupe <span class=\"kw-etio\">HACEK</span><br><em><span class=\"kw-etio\">Haemophilus</span>, Aggregatibacter, Cardiobacterium, Eikenella, Kingella</em></td><td><span class=\"kw-chiffre\">5 %</span></td><td>Croissance lente — <span class=\"kw-bio\">hémocultures</span> parfois négatives</td></tr>\n          <tr><td><span class=\"kw-etio\">Candida</span> et autres champignons (levures)</td><td><span class=\"kw-chiffre\">&lt; 5 %</span></td><td>EI fongiques — <span class=\"kw-alerte\">pronostic sévère</span></td></tr>\n          <tr><td>Autres — <span class=\"kw-etio\">Coxiella burnetii</span>, Bartonella, Brucella, <span class=\"kw-clinique\">Chlamydia</span>, Tropheryma whipplei</td><td><span class=\"kw-chiffre\">&lt; 5 %</span></td><td>EI à <span class=\"kw-bio\">hémocultures négatives</span></td></tr>\n          <tr><td>Aucun germe retrouvé malgré le bilan</td><td><span class=\"kw-chiffre\">5-10 %</span></td><td>EI à <span class=\"kw-bio\">hémocultures négatives</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum</em></p>","frequence":1},{"id":"152-5","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les portes d'entrée en fonction de l'agent infectieux","contenu":"<p>La <span class=\"kw-def\">porte d'entrée</span> est le site <span class=\"kw-etio\">infectieux</span> d'où part la <span class=\"kw-clinique\">bactériémie</span>. Elle <strong>dépend du micro-organisme</strong>, oriente le bilan, mais n'est identifiée que dans <span class=\"kw-chiffre\">~50 %</span> des cas.</p>\n      <table >\n        <thead><tr><th>Agent</th><th><span class=\"kw-clinique\">Porte d'entrée</span></th><th>Bilan orienté</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">S. aureus</span>, staph. à coagulase négative, <span class=\"kw-etio\">Candida</span></td><td><strong>Cutanée</strong> — plaies, cathéters veineux ou de dialyse, toxicomanie IV, geste peropératoire, stimulateur/<span class=\"kw-ttt\">défibrillateur</span></td><td><span class=\"kw-bio\">Culture du cathéter</span> ; <span class=\"kw-bio\">hémocultures</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Streptocoques oraux</span>, groupe <span class=\"kw-etio\">HACEK</span></td><td><strong>Bucco-dentaire</strong></td><td><span class=\"kw-imagerie\">Panoramique dentaire</span> ; consultation stomatologique</td></tr>\n          <tr><td><span class=\"kw-etio\">Streptocoques du groupe D</span> (S. gallolyticus)</td><td><strong>Digestive</strong> — cancer, polypes, diverticules coliques</td><td><span class=\"kw-alerte\">Coloscopie systématique</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Entérocoques</span></td><td><strong>Digestive</strong> et <strong>urinaire</strong></td><td><span class=\"kw-bio\">ECBU</span> ; <span class=\"kw-imagerie\">écho abdomino-pelvienne</span> ; ± <span class=\"kw-alerte\">coloscopie</span></td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"152-6","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les cardiopathies à risque d'EI du groupe B","contenu":"<p>Le <span class=\"kw-def\">groupe B</span> rassemble <span class=\"kw-clinique\">les</span> cardiopathies à <strong>risque intermédiaire</strong> d'EI :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Valvulopathies dégénératives</span> ;</li>\n        <li>Valvulopathies congénitales n'entrant pas dans le groupe A — ex. <span class=\"kw-etio\">bicuspidie aortique</span> ;</li>\n        <li><span class=\"kw-etio\">Cardiopathie post-rhumatismale</span> ;</li>\n        <li><span class=\"kw-etio\">Cardiomyopathie hypertrophique</span> ;</li>\n        <li><span class=\"kw-etio\">Stimulateur</span> et <span class=\"kw-etio\">défibrillateur</span> cardiaque implantables.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> Le groupe B est à risque intermédiaire : il <span class=\"kw-alerte\">ne relève pas de l'antibioprophylaxie</span>, réservée au seul <span class=\"kw-def\">groupe A</span> (haut risque). Tous deux relèvent en revanche de l'<span class=\"kw-def\">éducation à la santé</span>.</div>","frequence":0},{"id":"152-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques évocateurs EI","contenu":"<p>Le tableau évocateur d'EI repose sur l'association d'une <span class=\"kw-clinique\">fièvre</span> avec au moins l'un des éléments suivants : <strong>cardiopathie à risque</strong>, <strong>souffle cardiaque</strong>, <strong>accident <span class=\"kw-etio\">ischémique</span></strong>, <strong><span class=\"kw-def\">purpura</span></strong> ou <strong>lombalgie</strong>.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">infectieux</span></span></td><td><span class=\"kw-clinique\">Fièvre</span> ; <span class=\"kw-clinique\">AEG</span> ; <span class=\"kw-clinique\">splénomégalie</span> (<span class=\"kw-chiffre\">20-30 %</span>)</td></tr>\n          <tr><td>Signes cardiaques</td><td><strong>Souffle :</strong> apparition ou modification d'un <span class=\"kw-clinique\">souffle</span> — grande valeur diagnostique ; <span class=\"kw-alerte\">son absence n'élimine pas le diagnostic</span><br><strong><span class=\"kw-etio\">Insuffisance cardiaque</span> :</strong> <span class=\"kw-clinique\">fébrile</span>, surtout gauche<br><strong>Conduction :</strong> <span class=\"kw-clinique\">syncope</span> ou <span class=\"kw-clinique\">lipothymie</span> par <span class=\"kw-alerte\">BAV</span> (<span class=\"kw-clinique\">abcès</span> septal)<br><strong>Péricardite :</strong> plus rare</td></tr>\n          <tr><td>Phénomènes <strong>vasculaires</strong><br>(emboles septiques)</td><td><span class=\"kw-clinique\">Lésions de Janeway</span> — <span class=\"kw-clinique\">érythème</span> palmoplantaire indolore<br><span class=\"kw-clinique\">Hémorragies sous-unguéales</span> « en flammèche »<br>Emboles artériels ; anévrismes mycotiques</td></tr>\n          <tr><td>Phénomènes <strong>immunologiques</strong><br>(complexes immuns)</td><td>Faux <span class=\"kw-clinique\">panaris</span> d'<span class=\"kw-clinique\">Osler</span> — nodosités douloureuses, fugaces, pulpe des doigts/orteils<br><span class=\"kw-clinique\">Taches de Roth</span> — exsudats hémorragiques rétiniens (<span class=\"kw-imagerie\">fond d'œil</span>)<br><span class=\"kw-bio\">Glomérulonéphrite</span> ; <span class=\"kw-bio\">facteur rhumatoïde</span><br><span class=\"kw-clinique\">Purpura vasculaire</span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/152/signes-peripheriques.jpg\"\n             alt=\"Quatre signes périphériques de l'endocardite infectieuse : hémorragie sous-unguéale en flammèche, nodosité d'Osler à la pulpe des doigts, tache de Roth au fond d'œil, lésion de Janeway palmaire\"\n             loading=\"lazy\">\n        <figcaption>Signes périphériques de l'<span class=\"kw-def\">endocardite</span> infectieuse — hémorragie sous-unguéale « en flammèche », faux <span class=\"kw-clinique\">panaris</span> d'Osler (nodosité douloureuse, pulpe des doigts), tache de Roth (exsudat <span class=\"kw-etio\">hémorragique</span> rétinien) et <span class=\"kw-clinique\">lésion</span> de Janeway (érythème palmoplantaire indolore). Source : fiche source EDN item 152.</figcaption>\n      </figure>\n      <p>Cette planche illustre <span class=\"kw-clinique\">les</span> quatre signes périphériques : l'<span class=\"kw-clinique\">hémorragie sous-unguéale</span> et la <span class=\"kw-clinique\">lésion de Janeway</span> sont des phénomènes <strong>vasculaires</strong> (emboles septiques) ; la <span class=\"kw-clinique\">nodosité d'Osler</span> et la <span class=\"kw-clinique\">tache de Roth</span> sont des phénomènes <strong>immunologiques</strong> (dépôts de complexes immuns).</p>\n      <div class=\"callout callout-warn\"><strong>Discriminant EDN — Osler <span class=\"kw-bio\">vs</span> Janeway.</strong> <span class=\"kw-clinique\">Osler</span> = nodosité <span class=\"kw-alerte\">douloureuse</span>, phénomène <strong>immunologique</strong>. <span class=\"kw-clinique\">Janeway</span> = <span class=\"kw-clinique\">macule</span> <span class=\"kw-alerte\">indolore</span>, phénomène <strong>vasculaire</strong> (embole septique).</div>\n      <div class=\"callout callout-warn\"><strong>Tableaux trompeurs.</strong> <span class=\"kw-clinique\">Fièvre</span> nue aiguë ou prolongée, <span class=\"kw-clinique\">arthralgies</span> ou <span class=\"kw-clinique\">lombalgies fébriles</span>, forme révélée par une complication inaugurale, ou alternance <span class=\"kw-clinique\">fièvre</span> / apyrexie — la <span class=\"kw-alerte\">récidive de la fièvre à l'arrêt d'une antibiothérapie</span> est très évocatrice.</div>\n      <p><strong>Forme aiguë <span class=\"kw-bio\">vs</span> subaiguë</strong> — la forme <span class=\"kw-alerte\">aiguë</span> (<span class=\"kw-etio\">S. aureus</span>) associe <span class=\"kw-def\">sepsis</span> au premier plan, <span class=\"kw-etio\">insuffisance cardiaque</span> et risque d'<span class=\"kw-etio\">AVC</span>. L'<span class=\"kw-def\">endocardite</span> <span class=\"kw-def\">subaiguë d'Osler</span> (<span class=\"kw-etio\">streptocoque</span>, <span class=\"kw-etio\">entérocoque</span>) évolue sur plusieurs semaines : <span class=\"kw-clinique\">fièvre &gt; 8 jours</span>, <span class=\"kw-clinique\">AEG</span>, phénomènes auto-immuns circulants.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë</em></p>","frequence":2},{"id":"152-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche initiale du diagnostic microbiologique","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-bio\">hémocultures</span> sont le pilier microbiologique : elles isolent le germe dans <span class=\"kw-chiffre\">~90 %</span> des cas. Modalités à connaître :</p>\n      <ul>\n        <li><strong><span class=\"kw-chiffre\">3 prélèvements</span></strong> veineux sur <span class=\"kw-chiffre\">24 h</span>, espacés d'au moins <span class=\"kw-chiffre\">1 h</span>, mis en <span class=\"kw-bio\">culture aéro-anaérobie</span> ;</li>\n        <li>En cas de <span class=\"kw-def\">sepsis</span> : <span class=\"kw-chiffre\">2-3 hémocultures en &lt; 1 h</span> avant de démarrer l'<span class=\"kw-ttt\">antibiothérapie</span> urgente ;</li>\n        <li>Volume de sang optimal <span class=\"kw-chiffre\">40-60 mL</span> (3 paires) — il conditionne la <span class=\"kw-bio\">sensibilité</span> de l'examen ;</li>\n        <li>Chaque <span class=\"kw-bio\">hémoculture</span> sur une <strong><span class=\"kw-ttt\">ponction</span> veineuse distincte</strong> ;</li>\n        <li>À réaliser <strong>même en l'absence de <span class=\"kw-clinique\">fièvre</span></strong> ou de <span class=\"kw-clinique\">frissons</span> ;</li>\n        <li><span class=\"kw-alerte\">Signaler la suspicion d'EI au laboratoire</span> — culture prolongée nécessaire (jusqu'à <span class=\"kw-chiffre\">14 jours</span>) pour <span class=\"kw-clinique\">les</span> germes à croissance difficile.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Deux pièges.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-bio\">hémocultures</span> ne doivent <span class=\"kw-ci\">pas être prélevées sur un cathéter en place</span> ; et elles sont faites <strong>même sans <span class=\"kw-clinique\">fièvre</span></strong> — la <span class=\"kw-alerte\">bactériémie de l'EI est permanente</span>.</div>","frequence":0},{"id":"152-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la démarche du diagnostic microbiologique quand les hémocultures initiales sont négatives","contenu":"<p>Une EI à <span class=\"kw-bio\">hémocultures négatives</span> représente <span class=\"kw-chiffre\">~10 %</span> des cas. Trois grands mécanismes :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Faux négatif / non <span class=\"kw-etio\">infectieux</span></td><td><span class=\"kw-alerte\">Antibiothérapie préalable</span> aux <span class=\"kw-bio\">hémocultures</span> ; endocardites non infectieuses (<span class=\"kw-etio\">lupus</span>, <span class=\"kw-etio\">SAPL</span>, <span class=\"kw-etio\">cancer</span>)</td></tr>\n          <tr><td>Germes à croissance lente ou difficile</td><td><span class=\"kw-etio\">Streptocoques déficients</span> ; groupe <span class=\"kw-etio\">HACEK</span> ; <span class=\"kw-etio\">Brucella</span> ; <span class=\"kw-etio\">champignons</span></td></tr>\n          <tr><td>Germes intracellulaires<br>(<span class=\"kw-bio\">PCR</span> / <span class=\"kw-bio\">sérologie</span> obl<span class=\"kw-chiffre\">iga</span>toire)</td><td><span class=\"kw-etio\">Coxiella burnetii</span> ; <span class=\"kw-etio\">Chlamydia</span> ; <span class=\"kw-etio\">Bartonella</span> ; <span class=\"kw-etio\">Tropheryma whipplei</span> ; <span class=\"kw-etio\">Mycoplasma</span> ; <span class=\"kw-etio\">Legionella</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Démarche diagnostique</strong> :</p>\n      <ul>\n        <li>Si <span class=\"kw-alerte\">ATB préalable</span> → <span class=\"kw-alerte\">interrompre</span> <span class=\"kw-clinique\">les</span> antibiotiques, attendre <span class=\"kw-chiffre\">≥ 72 h</span>, puis répéter <span class=\"kw-chiffre\">3 hémocultures</span> sur <span class=\"kw-chiffre\">24 h</span> — sauf si un traitement urgent est indispensable (<span class=\"kw-imagerie\">végétation</span>, <span class=\"kw-clinique\">abcès</span>, destruction valvulaire, <span class=\"kw-def\">sepsis</span>) ;</li>\n        <li>Sans ATB préalable, présomption forte → techniques spéciales d'<span class=\"kw-bio\">hémoculture</span>, <span class=\"kw-bio\">sérologies</span> Coxiella burnetii et Bartonella, <span class=\"kw-bio\">amplification génique (PCR)</span> ;</li>\n        <li>Si le patient est opéré → analyse de la <strong>pièce chirurgicale</strong> : <span class=\"kw-bio\">histologie</span>, <span class=\"kw-bio\">culture</span>, ± <span class=\"kw-bio\">PCR</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Distracteurs EDN.</strong> La maladie de Lyme (<span class=\"kw-etio\">Borrelia</span>) ne donne <span class=\"kw-alerte\">pas</span> d'<span class=\"kw-def\">endocardite</span> ; la <span class=\"kw-etio\">tuberculose</span> non plus.</div>","frequence":0},{"id":"152-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche initiale du diagnostic échocardiographie en cas de suspicion d'EI","contenu":"<p>L'<span class=\"kw-imagerie\">échographie cardiaque</span> est, avec <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span>, l'un des deux <strong>piliers diagnostiques</strong> de l'EI.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th><th>Sensibilité</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">ETT</span> — transthoracique</td><td><strong>1ʳᵉ intention, systématique</strong> dans tous <span class=\"kw-clinique\">les</span> cas</td><td><span class=\"kw-chiffre\">~70 %</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">ETO</span> — transœsophagienne</td><td>Si <span class=\"kw-imagerie\">ETT</span> positive ; ou <span class=\"kw-imagerie\">ETT</span> négative avec <span class=\"kw-alerte\">forte suspicion</span> ; ou présence de <strong>matériel intracardiaque</strong></td><td><span class=\"kw-chiffre\">≥ 90 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Une <span class=\"kw-imagerie\">échographie normale n'élimine pas</span> le diagnostic. En cas de forte suspicion clinique, elle doit être <strong>répétée à <span class=\"kw-chiffre\">J7-J10</span></strong> (<span class=\"kw-imagerie\">ETT</span> + <span class=\"kw-imagerie\">ETO</span>).</div>\n      <p>Le <span class=\"kw-def\">diagnostic positif</span> s'appuie sur <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-def\">critères diagnostiques</span> de Duke modifiés (<span class=\"kw-chiffre\">2023</span>)</strong>, qui combinent critères <span class=\"kw-alerte\">majeurs</span> et <span class=\"kw-alerte\">mineurs</span> :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Critères majeurs</span> (2)</th><th><span class=\"kw-def\">Critères mineurs</span> (5)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong><span class=\"kw-bio\">Hémocultures</span> positives pour l'EI :</strong>\n              <ul>\n                <li><span class=\"kw-chiffre\">≥ 2 hémocultures</span> à micro-organisme <strong>typique d'EI</strong> (<span class=\"kw-etio\">S. aureus</span>, <span class=\"kw-etio\">streptocoques oraux</span>, <span class=\"kw-etio\">S. gallolyticus</span>, <span class=\"kw-etio\">entérocoques</span>, <span class=\"kw-etio\">HACEK</span>) ;</li>\n                <li>ou <span class=\"kw-chiffre\">≥ 1</span> <span class=\"kw-bio\">hémoculture</span> ou <span class=\"kw-bio\">sérologie</span> positive à <span class=\"kw-etio\">Coxiella burnetii</span> (<span class=\"kw-bio\">IgG phase I > 1/800</span>).</li>\n              </ul>\n              <strong><span class=\"kw-imagerie\">Imagerie</span> positive pour <span class=\"kw-clinique\">les</span> lésions d'EI :</strong>\n              <ul>\n                <li><span class=\"kw-imagerie\">échographie cardiaque</span> (végétations, <span class=\"kw-clinique\">abcès</span>, faux anévrisme, fistule, destruction valvulaire, désinsertion de prothèse) ;</li>\n                <li>ou <span class=\"kw-imagerie\">TEP-scan</span> / <span class=\"kw-imagerie\">scintigraphie aux leucocytes marqués</span> ;</li>\n                <li>ou <span class=\"kw-imagerie\">scanner cardiaque</span> (<span class=\"kw-clinique\">abcès</span>, faux anévrisme, fistule).</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Terrain</span> : patient à haut risque ou risque intermédiaire d'EI, ou toxicomanie IV ;</li>\n                <li><span class=\"kw-clinique\">Fièvre</span> ≥ <span class=\"kw-chiffre\">38 °C</span> ;</li>\n                <li><span class=\"kw-clinique\">Phénomènes vasculaires</span> : embolies artérielles ou pulmonaires, anévrismes <span class=\"kw-etio\">infectieux</span> (mycotiques), hémorragies, placards de Janeway ;</li>\n                <li><span class=\"kw-clinique\">Phénomènes immunologiques</span> : glomérulonéphrite, nodosités d'Osler, taches de Roth, facteurs rhumatoïdes ;</li>\n                <li><span class=\"kw-bio\">Argument microbiologique</span> n'entrant pas dans la définition d'un <span class=\"kw-def\">critère majeur</span> (<span class=\"kw-bio\">hémocultures</span>, <span class=\"kw-bio\">sérologies</span>).</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Seuils diagnostiques (EI certaine).</strong> <span class=\"kw-chiffre\">2 critères majeurs</span>, ou <span class=\"kw-chiffre\">1 majeur + 3 mineurs</span>, ou <span class=\"kw-chiffre\">5 critères mineurs</span> (à défaut d'un critère histologique). <strong>EI possible</strong> : 1 majeur + 1-<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> min</span>eurs, ou 3 mineurs.</div>","frequence":1},{"id":"152-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les arguments échocardiographiques du diagnostic d'EI","contenu":"<p>L'<span class=\"kw-imagerie\">échographie cardiaque</span> (<span class=\"kw-imagerie\">ETT</span> puis <span class=\"kw-imagerie\">ETO</span>) recherche <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">lésions caractéristiques d'EI</span> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Végétations</span> — <span class=\"kw-clinique\">lésion</span> élémentaire proliférante de l'EI ;</li>\n        <li><span class=\"kw-imagerie\">Destructions valvulaires</span> — perforation, mutilation, <span class=\"kw-alerte\">rupture</span> de cordage ;</li>\n        <li><span class=\"kw-clinique\">Abcès</span> et <span class=\"kw-clinique\">faux anévrisme</span> ;</li>\n        <li><span class=\"kw-imagerie\">Fistules intracardiaques</span> ;</li>\n        <li><span class=\"kw-imagerie\">Désinsertion de prothèse</span> et <span class=\"kw-imagerie\">fuite paraprothétique</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Critère de</span> Duke.</strong> Une imagerie positive pour ces lésions est un <span class=\"kw-alerte\">critère majeur</span> des <span class=\"kw-def\">critères de</span> Duke modifiés (<span class=\"kw-chiffre\">2023</span>), au même titre qu'un <span class=\"kw-imagerie\">TEP-scanner</span> ou une <span class=\"kw-imagerie\">scintigraphie aux leucocytes marqués</span> positifs, ou un <span class=\"kw-imagerie\">scanner cardiaque</span> montrant <span class=\"kw-clinique\">abcès</span>, faux anévrisme ou fistule.</div>","frequence":0},{"id":"152-12","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir hiérarchiser les examens complémentaires en fonction de l'état clinique du patient (hémocultures, échocardiographie, autres examens complémentaires)","contenu":"<p>Le bilan se hiérarchise autour des <strong>deux piliers</strong> — <span class=\"kw-bio\">hémocultures</span> et <span class=\"kw-imagerie\">échographie cardiaque</span> — complétés selon l'état clinique du patient.</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Piliers diagnostiques</td><td><strong><span class=\"kw-bio\">Hémocultures</span> :</strong> <span class=\"kw-bio\">mise en évidence du germe</span><br><strong><span class=\"kw-imagerie\">Échographie cardiaque</span> :</strong> <span class=\"kw-imagerie\">ETT</span> puis <span class=\"kw-imagerie\">ETO</span> — confirme l'atteinte de l'endocarde</td></tr>\n          <tr><td>Si <span class=\"kw-imagerie\">échographie</span> non contributive</td><td><strong><span class=\"kw-imagerie\">TDM</span> cardiaque :</strong> <span class=\"kw-clinique\">abcès</span> non vus à l'écho, surtout si prothèse<br><strong><span class=\"kw-imagerie\">TEP-scanner 18-FDG</span> / <span class=\"kw-imagerie\">scintigraphie aux leucocytes marqués</span> :</strong> hyperfixation, EI sur prothèse ; dépiste <span class=\"kw-clinique\">les</span> localisations septiques</td></tr>\n          <tr><td>Biologie</td><td><strong><span class=\"kw-bio\">NFS</span> :</strong> <span class=\"kw-bio\">hyperleucocytose à PNN</span> ; <span class=\"kw-bio\">anémie</span> ; <span class=\"kw-bio\">thrombopénie</span><br><strong>Inflammation :</strong> <span class=\"kw-bio\">CRP</span> élevée<br><strong>Retentissement :</strong> <span class=\"kw-bio\">ionogramme</span> ; <span class=\"kw-bio\">créatininémie</span> ; <span class=\"kw-bio\">BU</span><br><strong>Immunologie :</strong> <span class=\"kw-bio\">facteur rhumatoïde</span> ; <span class=\"kw-bio\">complément</span> ; <span class=\"kw-bio\">cryoglobulinémie</span></td></tr>\n          <tr><td>Retentissement cardiaque</td><td><strong><span class=\"kw-bio\">ECG</span> :</strong> trouble de conduction (<span class=\"kw-alerte\">BAV</span>) ; <span class=\"kw-alerte\">ischémie myocardique</span> (embolie coronarienne)</td></tr>\n          <tr><td>Localisations secondaires</td><td><strong><span class=\"kw-imagerie\">RXT</span> :</strong> <span class=\"kw-clinique\">OAP</span> (EI cœur gauche) ou pneumopathie (EI cœur droit)<br><strong><span class=\"kw-imagerie\">TDM corps entier injectée</span> :</strong> localisations septiques ; anévrismes mycotiques<br><strong><span class=\"kw-imagerie\">IRM cérébrale</span> :</strong> plus sensible que le <span class=\"kw-imagerie\">scanner</span>, sur point d'appel<br><strong><span class=\"kw-imagerie\">Coronarographie</span>, <span class=\"kw-bio\">troponine</span> :</strong> si embolie coronarienne suspectée</td></tr>\n        </tbody>\n      </table>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/infective-endocarditis","label":"Radiopaedia : Infective endocarditis"}]},{"id":"152-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principales localisations emboliques en cas d'EI","contenu":"<p><span class=\"kw-clinique\">Les</span> emboles proviennent des <span class=\"kw-def\">végétations</span> ; leur localisation dépend du côté du cœur atteint.</p>\n      <table >\n        <thead><tr><th>Origine</th><th>Localisations emboliques</th></tr></thead>\n        <tbody>\n          <tr><td>EI du <strong>cœur gauche</strong><br>(emboles systémiques)</td><td><strong>Cérébral :</strong> <span class=\"kw-etio\">AVC</span>, <span class=\"kw-clinique\">AIT</span>, <span class=\"kw-clinique\">convulsions</span>, <span class=\"kw-clinique\">syndrome méningé</span> — <span class=\"kw-chiffre\">~25 %</span> des cas, <span class=\"kw-alerte\">2ᵉ cause de décès</span><br><strong>Viscéral :</strong> <span class=\"kw-clinique\">rate</span>, <span class=\"kw-clinique\">reins</span>, <span class=\"kw-clinique\">foie</span> — <span class=\"kw-clinique\">abcès</span> ou <span class=\"kw-clinique\">infarctus</span><br><strong>Ostéo-articulaire :</strong> <span class=\"kw-clinique\">arthrite</span> ; <span class=\"kw-clinique\">spondylodiscite</span><br><strong>Membres :</strong> <span class=\"kw-clinique\">ischémie aiguë</span> ou subaiguë<br><strong>Coronaire :</strong> <span class=\"kw-clinique\">ischémie myocardique</span></td></tr>\n          <tr><td>EI du <strong>cœur droit</strong></td><td><strong>Embolies pulmonaires septiques :</strong> fréquemment multiples — <span class=\"kw-clinique\">infarctus pulmonaires</span>, <span class=\"kw-clinique\">abcès</span><br><strong>Pneumopathies :</strong> <span class=\"kw-clinique\">récidivantes</span> et <span class=\"kw-clinique\">abcédées</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Anévrismes mycotiques.</strong> Anévrismes <span class=\"kw-etio\">infectieux</span> de toute localisation — ils exposent à une <span class=\"kw-alerte\">hémorragie cataclysmique</span> par <span class=\"kw-alerte\">rupture</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-etio\">AVC</span> · 156 — Infection ostéo-articulaire</em></p>","frequence":1},{"id":"152-14","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir quand une antibiothérapie probabiliste est indiquée en cas de suspicion d'EI","contenu":"<p>L'<span class=\"kw-ttt\">antibiothérapie probabiliste</span> est instaurée <strong>après <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span></strong> et <strong>avant leur résultat</strong>. Elle n'est justifiée que dans trois situations :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Forte suspicion</span> d'EI — surtout si <span class=\"kw-imagerie\">images évocatrices</span> à l'<span class=\"kw-imagerie\">échographie cardiaque</span> ;</li>\n        <li><span class=\"kw-alerte\">Sepsis sévère</span> ;</li>\n        <li><span class=\"kw-alerte\">Indication chirurgicale urgente</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Règle d'or.</strong> Hors de ces situations, on <strong>attend la <span class=\"kw-bio\">documentation microbiologique</span></strong>. Dans tous <span class=\"kw-clinique\">les</span> cas, les <span class=\"kw-bio\">hémocultures</span> sont prélevées <em>avant</em> toute <span class=\"kw-ttt\">antibiothérapie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":0},{"id":"152-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement antibiotique de l'EI","contenu":"<p>L'EI impose une <strong><span class=\"kw-alerte\">hospitalisation</span> systématique</strong> et une prise en charge multidisciplinaire. L'objectif est l'<span class=\"kw-def\">éradication microbienne définitive</span> au site de l'infection — difficile à obtenir pour cinq raisons :</p>\n      <ul>\n        <li><span class=\"kw-def\">Endocarde faiblement vascularisé</span> ;</li>\n        <li>La <span class=\"kw-def\">fibrine</span> protège <span class=\"kw-clinique\">les</span> bactéries de la phagocytose ;</li>\n        <li><span class=\"kw-def\">Inoculum bactérien important</span> ;</li>\n        <li>Bactéries en <span class=\"kw-def\">phase de croissance lente</span> ;</li>\n        <li><span class=\"kw-def\">Bactériémie permanente</span> avec recolonisation régulière des végétations.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Principe</th><th>Modalité</th></tr></thead>\n        <tbody>\n          <tr><td>Type d'<span class=\"kw-ttt\">antibiothérapie</span></td><td><span class=\"kw-ttt\">Bactéricide</span> ; molécules <strong>synergiques</strong> ; <span class=\"kw-alerte\">fortes doses</span> ; voie <strong>IV</strong></td></tr>\n          <tr><td>Durée</td><td><span class=\"kw-chiffre\">4 à 6 semaines</span> — non modifiée même si une <span class=\"kw-ttt\">chirurgie</span> est nécessaire</td></tr>\n          <tr><td><span class=\"kw-def\">Surveillance</span> de l'efficacité</td><td>Régression de la <span class=\"kw-clinique\">fièvre</span> et du <span class=\"kw-bio\">syndrome inflammatoire</span> ; <span class=\"kw-bio\">stérilisation des hémocultures</span> ; <span class=\"kw-clinique\">évolution</span> favorable à l'<span class=\"kw-imagerie\">écho</span> ; absence de complications</td></tr>\n          <tr><td><span class=\"kw-def\">Surveillance</span> de la tolérance</td><td>Doses adaptées aux fonctions rénale et hépatique ; <span class=\"kw-bio\">dosages plasmatiques</span> des <span class=\"kw-ttt\">aminosides</span> et de la <span class=\"kw-ttt\">vancomycine</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Deux pièges.</strong> Le traitement est <span class=\"kw-alerte\">bactéricide</span>, jamais bactériostatique. La <span class=\"kw-ttt\">gentamicine</span> ne doit pas dépasser <span class=\"kw-chiffre\">15 jours</span> — <span class=\"kw-ci\">néphrotoxicité des aminosides</span>.</div>\n      <div class=\"callout callout-danger\"><strong>Indications chirurgicales en phase active</strong> (présentes dans <span class=\"kw-chiffre\">50 %</span> des cas) — trois familles :\n        <ul>\n          <li><strong>Hémodynamiques :</strong> <span class=\"kw-alerte\">insuffisance cardiaque gauche</span> réfractaire ou <span class=\"kw-alerte\">choc cardiogénique</span>, ou <span class=\"kw-alerte\">régurgitation</span> aiguë / signe échographique de mauvaise tolérance ;</li>\n          <li><strong>Infectieuses :</strong> <span class=\"kw-alerte\">infection non contrôlée localement</span> (<span class=\"kw-clinique\">abcès</span>, fistule, faux anévrisme, végétation croissante, désinsertion de prothèse, BAV) ; EI <span class=\"kw-etio\">fongique</span> ou à germes multirésistants ; persistance d'<span class=\"kw-bio\">hémocultures</span> positives malgré <span class=\"kw-chiffre\">> 7 jours</span> d'ATB ;</li>\n          <li><strong>Emboliques :</strong> <span class=\"kw-clinique\">végétation du cœur gauche > 10 mm</span> persistante après embolie malgré ATB adaptée, ou associée à une autre indication chirurgicale.</li>\n        </ul>\n        <span class=\"kw-ci\">Une complication neurologique peut contre-indiquer temporairement la circulation extracorporelle</span> (imagerie cérébrale avant toute <span class=\"kw-ttt\">chirurgie</span> valvulaire).\n      </div>","frequence":0},{"id":"152-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de prise en charge de la porte d'entrée d'une EI","contenu":"<p>Le <strong>traitement de la <span class=\"kw-clinique\">porte d'entrée</span></strong> est indispensable : sans lui, le risque de <span class=\"kw-alerte\">récidive</span> persiste. Sa recherche et sa prise en charge dépendent du germe identifié.</p>\n      <table >\n        <thead><tr><th>Origine</th><th>Germes</th><th>Prise en charge</th></tr></thead>\n        <tbody>\n          <tr><td>Cutanée</td><td><span class=\"kw-etio\">S. aureus</span>, staph. à coagulase négative</td><td>Examen du revêtement cutané ; <span class=\"kw-bio\">ablation et culture du cathéter</span></td></tr>\n          <tr><td>Bucco-dentaire</td><td><span class=\"kw-etio\">Streptocoques oraux</span>, <span class=\"kw-etio\">HACEK</span></td><td><span class=\"kw-imagerie\">Panoramique dentaire</span> ; consultation et soins stomatologiques</td></tr>\n          <tr><td>Digestive</td><td><span class=\"kw-etio\">S. gallolyticus</span>, <span class=\"kw-etio\">entérocoques</span></td><td><span class=\"kw-alerte\">Coloscopie totale</span> ; <span class=\"kw-imagerie\">imagerie abdominale</span> et des voies biliaires ; recherche d'une <span class=\"kw-alerte\">tumeur colique</span></td></tr>\n          <tr><td>Urinaire</td><td><span class=\"kw-etio\">Entérocoques</span></td><td><span class=\"kw-bio\">ECBU</span> ; <span class=\"kw-imagerie\">échographie</span> ou <span class=\"kw-imagerie\">scanner</span> des voies urinaires</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"152-17","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes d'éducation à la santé après un épisode d'EI","contenu":"<p>L'éducation à la santé concerne <strong>tous <span class=\"kw-clinique\">les</span> patients porteurs d'une cardiopathie à risque</strong> d'EI (<span class=\"kw-def\">groupe A</span> ou <span class=\"kw-def\">groupe B</span>). Mesures à connaître :</p>\n      <ul>\n        <li>Maintenir une bonne <strong><span class=\"kw-clinique\">hygiène bucco-dentaire</span></strong> ;</li>\n        <li><span class=\"kw-clinique\">Consultation chez le dentiste</span> — <span class=\"kw-chiffre\">2×/an</span> si cardiopathie à haut risque, <span class=\"kw-chiffre\">1×/an</span> pour <span class=\"kw-clinique\">les</span> autres ;</li>\n        <li><span class=\"kw-clinique\">Désinfecter les plaies</span> ;</li>\n        <li>Éradiquer <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">colonisations bactériennes chroniques</span> — cutanées et urinaires ;</li>\n        <li>Traiter <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">infections bactériennes locales</span> par antibiotiques ;</li>\n        <li><span class=\"kw-clinique\">Asepsie stricte</span> lors des procédures à risque de <span class=\"kw-clinique\">bactériémie</span> ;</li>\n        <li>Éviter <span class=\"kw-clinique\">les</span> effractions cutanées — <span class=\"kw-ci\">tatouages</span>, <span class=\"kw-ci\">piercings</span> ;</li>\n        <li>Limiter et renouveler <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">voies veineuses</span> ;</li>\n        <li>Éviter l'<span class=\"kw-ci\">automédication par antibiotiques</span> et consulter rapidement en cas de <span class=\"kw-clinique\">fièvre</span>.</li>\n      </ul>","frequence":0},{"id":"152-18","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de l'antibioprophylaxie de l'EI (groupe de cardiopathie à risque, gestes à risque)","contenu":"<p>Un patient à risque reçoit une <strong>carte de patient à risque d'EI</strong>, à présenter avant toute procédure bucco-dentaire. L'<span class=\"kw-ttt\">antibioprophylaxie</span> n'est indiquée qu'à la <strong>conjonction stricte</strong> de deux conditions :</p>\n      <table >\n        <thead><tr><th>Condition</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td>1 · Cardiopathie</td><td>Uniquement le <strong><span class=\"kw-def\">groupe A</span></strong> — cardiopathie à <span class=\"kw-alerte\">haut risque</span></td></tr>\n          <tr><td>2 · Geste</td><td>Soin dentaire à haut risque de <span class=\"kw-clinique\">bactériémie</span> : manipulation de la <strong>gencive</strong> ou de la <strong>région périapicale</strong> de la dent (<span class=\"kw-alerte\">détartrage inclus</span>) ; <span class=\"kw-clinique\">effraction de la muqueuse</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Ce qui ne relève PAS de l'<span class=\"kw-ttt\">antibioprophylaxie</span>.</strong> Pas après un <span class=\"kw-alerte\">traumatisme gingival</span> ou dentaire ; <span class=\"kw-alerte\">pas avant une coloscopie</span> ; ni avant une <span class=\"kw-alerte\">intubation</span> ; ni avant aucune autre <span class=\"kw-ttt\">chirurgie</span>.</div>\n      <p><strong>Modalités</strong> — <span class=\"kw-chiffre\">30-60 min avant</span> le soin :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Amoxicilline</span> (ou ampicilline) <span class=\"kw-chiffre\">2 g</span> per os ou IV ; ou <span class=\"kw-ttt\">céfazoline</span> / <span class=\"kw-ttt\">ceftriaxone</span> <span class=\"kw-chiffre\">1 g</span> IM ou IV ;</li>\n        <li>Si <span class=\"kw-ci\">allergie aux pénicillines</span> : <span class=\"kw-ttt\">céfalexine</span> <span class=\"kw-chiffre\">2 g</span> PO, <span class=\"kw-ttt\">azithromycine</span> <span class=\"kw-chiffre\">500 mg</span> PO ou <span class=\"kw-ttt\">doxycycline</span> <span class=\"kw-chiffre\">100 mg</span> PO.</li>\n      </ul>","frequence":2},{"id":"152-19","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications des EI : complications cardiaques, complications emboliques, complications infectieuses","contenu":"<p><span class=\"kw-clinique\">Les</span> complications de l'EI se répartissent en trois groupes — c'est le plan même de l'intitulé officiel.</p>\n      <table >\n        <thead><tr><th>Type</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr><td>Cardiaques</td><td>Destruction valvulaire → <span class=\"kw-alerte\">régurgitation</span> valvulaire ou paraprothétique ; <span class=\"kw-alerte\">insuffisance cardiaque aiguë</span> (<span class=\"kw-clinique\">OAP</span>, <span class=\"kw-clinique\">choc cardiogénique</span>) ; <span class=\"kw-clinique\">abcès</span> → <span class=\"kw-alerte\">BAV</span> (<span class=\"kw-clinique\">abcès</span> septal des EI aortiques), et par <span class=\"kw-alerte\">rupture</span> → <span class=\"kw-clinique\">faux anévrisme</span> ou <span class=\"kw-clinique\">fistule intracardiaque</span> ; <span class=\"kw-clinique\">désinsertion de prothèse</span></td></tr>\n          <tr><td>Emboliques</td><td>Emboles systémiques (cœur gauche) → <span class=\"kw-etio\">AVC</span>, <span class=\"kw-clinique\">abcès</span> spléniques / rénaux / hépatiques ; <span class=\"kw-clinique\">embolies pulmonaires septiques</span> (cœur droit) ; <span class=\"kw-alerte\">anévrismes infectieux (mycotiques)</span> à risque <span class=\"kw-etio\">hémorragique</span></td></tr>\n          <tr><td>Infectieuses</td><td><span class=\"kw-alerte\">Choc septique</span> ; foyers <span class=\"kw-etio\">infectieux</span> à distance — <span class=\"kw-clinique\">spondylodiscite</span>, <span class=\"kw-clinique\">arthrite</span>, <span class=\"kw-clinique\">méningite</span>, <span class=\"kw-clinique\">abcès</span> ; infection localement non contrôlée</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-clinique\">Les</span> deux causes de décès.</strong> L'<span class=\"kw-etio\">insuffisance cardiaque</span> est la <span class=\"kw-chiffre\">1ʳᵉ</span> cause de <span class=\"kw-def\">mortalité</span> de l'EI, les <span class=\"kw-alerte\">emboles cérébraux</span> la <span class=\"kw-chiffre\">2ᵉ</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-etio\">Insuffisance cardiaque</span> · 340 — <span class=\"kw-etio\">AVC</span></em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> diagnostique et thérapeutique :</strong> <span class=\"kw-def\">mortalité</span> hospitalière <span class=\"kw-chiffre\">15-30 %</span> — 1ʳᵉ cause de décès = <span class=\"kw-etio\">insuffisance cardiaque</span>, 2ᵉ = <span class=\"kw-alerte\">emboles cérébraux</span>.<br><strong><span class=\"kw-bio\">Hémocultures</span> AVANT toute <span class=\"kw-ttt\">antibiothérapie</span> :</strong> <span class=\"kw-chiffre\">3 prélèvements</span> sur <span class=\"kw-chiffre\">24 h</span> espacés de <span class=\"kw-chiffre\">≥ 1 h</span> ; en cas de <span class=\"kw-alerte\">sepsis</span>, <span class=\"kw-chiffre\">2-3 hémocultures en &lt; 1 h</span> avant de démarrer l’<span class=\"kw-ttt\">ATB</span> urgente.<br><strong>ATB probabiliste urgente</strong> seulement si <span class=\"kw-alerte\">forte suspicion</span> (image à l’<span class=\"kw-imagerie\">écho</span>), <span class=\"kw-alerte\">sepsis sévère</span> ou <span class=\"kw-alerte\">indication chirurgicale urgente</span>.<br><strong><span class=\"kw-imagerie\">Échographie</span> :</strong> <span class=\"kw-imagerie\">ETT</span> d’emblée ; si normale mais suspicion forte, répéter <span class=\"kw-imagerie\">ETT + ETO à J7-J10</span>.</p>","hospit":"<p><strong><span class=\"kw-alerte\">Hospitalisation</span> systématique</strong> avec prise en charge multidisciplinaire (« endocarditis team » : cardiologue, infectiologue, chirurgien).<br><strong><span class=\"kw-ttt\">Chirurgie</span> cardiaque</strong> indiquée en phase active dans <span class=\"kw-chiffre\">50 %</span> des cas — discuter d’emblée le recours à un centre chirurgical.<br><strong>EI sur matériel</strong> (sonde de <span class=\"kw-etio\">stimulateur</span>/<span class=\"kw-etio\">défibrillateur</span>, <span class=\"kw-etio\">cathéter veineux central</span>, EI du cœur droit) : <span class=\"kw-ttt\">retrait du matériel</span> en plus des antibiotiques.<br><strong>Avant toute chirurgie valvulaire :</strong> <span class=\"kw-imagerie\">imagerie cérébrale</span> — une <span class=\"kw-alerte\">complication neurologique</span> peut contre-indiquer temporairement la circulation extracorporelle.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Insuffisance cardiaque aiguë fébrile</span> — <span class=\"kw-clinique\">OAP</span>, <span class=\"kw-alerte\">choc cardiogénique</span> (1ʳᵉ cause de décès)</li><li><span class=\"kw-alerte\">Régurgitation valvulaire aiguë</span> ou désinsertion de prothèse</li><li><span class=\"kw-alerte\">BAV</span> par <span class=\"kw-clinique\">abcès</span> septal (surtout EI aortique) → <span class=\"kw-clinique\">syncope</span>, <span class=\"kw-clinique\">lipothymie</span></li><li><span class=\"kw-alerte\">Sepsis sévère</span> / <span class=\"kw-alerte\">choc septique</span></li><li>Embole cérébral : <span class=\"kw-etio\">AVC</span>, <span class=\"kw-clinique\">syndrome méningé</span>, <span class=\"kw-clinique\">troubles de la conscience</span> (2ᵉ cause de décès)</li><li><span class=\"kw-alerte\">Anévrisme mycotique</span> — risque d’<span class=\"kw-alerte\">hémorragie cataclysmique</span> par <span class=\"kw-alerte\">rupture</span></li><li><span class=\"kw-clinique\">Végétation du cœur gauche</span> <span class=\"kw-chiffre\">&gt; 10 mm</span> (risque <span class=\"kw-etio\">embolique</span>)</li><li>EI <span class=\"kw-etio\">fongique</span> ou à <span class=\"kw-etio\">germes multirésistants</span></li><li><span class=\"kw-alerte\">Hémocultures positives persistantes</span> malgré <span class=\"kw-chiffre\">&gt; 7 jours</span> d’<span class=\"kw-ttt\">ATB</span></li><li><span class=\"kw-def\">Terrain</span> de mauvais <span class=\"kw-def\">pronostic</span> : <span class=\"kw-etio\">S. aureus</span>, EI sur <span class=\"kw-etio\">prothèse</span>, <span class=\"kw-imagerie\">abcès intracardiaque</span>, <span class=\"kw-imagerie\">végétation volumineuse</span></li></ul>","principes":"<p><strong><span class=\"kw-ttt\">Antibiothérapie</span> :</strong> <span class=\"kw-ttt\">bactéricide</span>, molécules <span class=\"kw-ttt\">synergiques</span>, fortes doses, voie <span class=\"kw-ttt\">IV</span>, <span class=\"kw-chiffre\">4 à 6 semaines</span> — durée non modifiée même si une <span class=\"kw-ttt\">chirurgie</span> est nécessaire.<br><strong>ATB probabiliste</strong> uniquement si <span class=\"kw-alerte\">forte suspicion</span> (image écho), <span class=\"kw-alerte\">sepsis sévère</span> ou <span class=\"kw-alerte\">indication chirurgicale urgente</span>, toujours <em>après</em> <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> et avant leur résultat.<br><strong>Toujours :</strong> <span class=\"kw-ttt\">traitement de la porte d’entrée</span> + prise en charge multidisciplinaire.</p><p><strong>ATB probabiliste — valve native ou prothèse &gt;<span class=\"kw-chiffre\"> 1 an</span></strong></p><ul><li><span class=\"kw-ttt\">Amoxicilline</span> + <span class=\"kw-ttt\">ceftriaxone</span> (ou <span class=\"kw-ttt\">oxacilline</span>) + <span class=\"kw-ttt\">gentamicine</span></li><li>Si <span class=\"kw-ci\">allergie aux pénicillines</span> : <span class=\"kw-ttt\">céfazoline</span> ou <span class=\"kw-ttt\">vancomycine</span> + <span class=\"kw-ttt\">gentamicine</span></li></ul><p><strong>ATB probabiliste — prothèse &lt;<span class=\"kw-chiffre\"> 1 an</span> ou EI non communautaire</strong></p><ul><li>Ne pas passer à côté d’un <span class=\"kw-etio\">SARM</span> : <span class=\"kw-ttt\">vancomycine</span> (ou <span class=\"kw-ttt\">daptomycine</span>) + <span class=\"kw-ttt\">gentamicine</span> + <span class=\"kw-ttt\">rifampicine</span></li><li><span class=\"kw-ttt\">Gentamicine</span> ≤ <span class=\"kw-chiffre\">15 jours</span> — <span class=\"kw-ci\">néphrotoxicité des aminosides</span></li></ul><p><strong><span class=\"kw-ttt\">Chirurgie</span> en phase active (<span class=\"kw-chiffre\">50 %</span> des cas)</strong></p><ul><li><strong>Hémodynamique :</strong> <span class=\"kw-alerte\">IC gauche réfractaire</span>, <span class=\"kw-alerte\">choc cardiogénique</span>, <span class=\"kw-alerte\">régurgitation aiguë</span> mal tolérée</li><li><strong>Infectieuse :</strong> <span class=\"kw-alerte\">infection non contrôlée</span> (<span class=\"kw-clinique\">abcès</span>, fistule, faux anévrisme, désinsertion, <span class=\"kw-alerte\">BAV</span>), EI <span class=\"kw-etio\">fongique</span>/<span class=\"kw-etio\">multirésistante</span>, <span class=\"kw-bio\">hémocultures</span> + malgré <span class=\"kw-chiffre\">&gt; 7 j</span> d’ATB</li><li><strong><span class=\"kw-etio\">Embolique</span> :</strong> <span class=\"kw-clinique\">végétation cœur gauche</span> <span class=\"kw-chiffre\">&gt; 10 mm</span> persistante après embolie ou associée à une autre indication</li><li><span class=\"kw-ci\">Complication neurologique</span> = <span class=\"kw-ci\">contre-indication</span> temporaire à la circulation extracorporelle (imagerie cérébrale préalable)</li></ul><p><strong>Mesures associées</strong></p><ul><li><span class=\"kw-ttt\">Traitement de la porte d’entrée</span> (sinon récidive) : soins dentaires, ablation/culture du <span class=\"kw-etio\">cathéter</span>, <span class=\"kw-imagerie\">coloscopie</span>, <span class=\"kw-bio\">ECBU</span>…</li><li>Traitement médical de l’<span class=\"kw-etio\">insuffisance cardiaque</span> ; <span class=\"kw-ttt\">retrait du matériel</span> (sonde, cathéter) si EI sur matériel</li><li><span class=\"kw-ci\">Pas d’antiagrégant ni d’anticoagulant curatif</span> (risque <span class=\"kw-etio\">hémorragique</span>, anévrisme mycotique) ; <span class=\"kw-ttt\">anticoagulation</span> préventive autorisée</li></ul><p><strong><span class=\"kw-def\">Prévention secondaire</span></strong></p><ul><li><strong>Éducation (groupe A et B) :</strong> <span class=\"kw-clinique\">hygiène bucco-dentaire</span>, dentiste <span class=\"kw-chiffre\">2×/an</span> (haut risque) ou <span class=\"kw-chiffre\">1×/an</span>, désinfection des plaies, <span class=\"kw-ci\">éviter tatouages/piercings</span> et <span class=\"kw-ci\">automédication antibiotique</span></li><li><strong><span class=\"kw-ttt\">Antibioprophylaxie</span> (groupe A seul + geste dentaire à risque) :</strong> <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">2 g</span> <span class=\"kw-chiffre\">30-60 min avant</span> ; si <span class=\"kw-ci\">allergie</span> : <span class=\"kw-ttt\">céfalexine</span>/<span class=\"kw-ttt\">azithromycine</span>/<span class=\"kw-ttt\">doxycycline</span></li><li><span class=\"kw-ci\">Pas d’antibioprophylaxie</span> avant <span class=\"kw-imagerie\">coloscopie</span>, <span class=\"kw-ttt\">intubation</span> ou autre <span class=\"kw-ttt\">chirurgie</span></li></ul>","suivi":"<p><strong>Efficacité :</strong> régression de la <span class=\"kw-clinique\">fièvre</span> et du <span class=\"kw-bio\">syndrome inflammatoire</span> (<span class=\"kw-bio\">CRP</span>) ; <span class=\"kw-bio\">hémocultures quotidiennes</span> jusqu’à stérilisation ; <span class=\"kw-clinique\">évolution</span> favorable à l’<span class=\"kw-imagerie\">écho</span> (<span class=\"kw-imagerie\">ETT</span>/<span class=\"kw-imagerie\">ETO</span> répétées).<br><strong>Tolérance :</strong> doses adaptées aux fonctions rénale/hépatique ; <span class=\"kw-bio\">dosages plasmatiques</span> des <span class=\"kw-ttt\">aminosides</span> et de la <span class=\"kw-ttt\">vancomycine</span> ; <span class=\"kw-bio\">créatininémie</span> (<span class=\"kw-ci\">néphrotoxicité gentamicine/vancomycine</span>).<br><strong>EI aortique :</strong> <span class=\"kw-bio\">ECG quotidien</span> — dépister un <span class=\"kw-alerte\">BAV</span> par <span class=\"kw-clinique\">abcès</span> septal.<br><strong>Guérison :</strong> seule l’<span class=\"kw-alerte\">absence de rechute</span> après arrêt de l’ATB l’affirme ; négativation des <span class=\"kw-bio\">hémocultures</span>, disparition de la <span class=\"kw-clinique\">fièvre</span> et du <span class=\"kw-clinique\">souffle</span> ne suffisent pas seules.</p><p><strong>Complications à dépister</strong></p><ul><li><strong>Cardiaques :</strong> <span class=\"kw-alerte\">régurgitation</span>, <span class=\"kw-alerte\">insuffisance cardiaque aiguë</span>, <span class=\"kw-clinique\">abcès</span> → <span class=\"kw-alerte\">BAV</span>, faux anévrisme, <span class=\"kw-clinique\">fistule</span>, désinsertion de prothèse</li><li><strong>Emboliques :</strong> <span class=\"kw-etio\">AVC</span>, <span class=\"kw-clinique\">abcès</span> spléniques/rénaux/hépatiques, <span class=\"kw-clinique\">embolies pulmonaires septiques</span> (cœur droit), <span class=\"kw-alerte\">anévrismes mycotiques</span></li><li><strong>Infectieuses :</strong> <span class=\"kw-alerte\">choc septique</span>, <span class=\"kw-clinique\">spondylodiscite</span>, <span class=\"kw-clinique\">arthrite</span>, <span class=\"kw-clinique\">méningite</span>, foyers <span class=\"kw-etio\">infectieux</span> non contrôlés</li></ul>"},"liensGlobaux":[{"href":"https://www.sfcardio.fr/page/chapitre-9-item-152-endocardite-infectieuse","label":"Collège SFC — Endocardite infectieuse (chap. 9, item 152)"},{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-152.pdf","label":"Collège Pilly — Endocardite (item 152, PDF)"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/49.%20Endocardite%20infectieuse.pdf","label":"Collège CE-MIR — Endocardite infectieuse (PDF)"},{"href":"https://fr.wikipedia.org/wiki/Hypertension_art%C3%A9rielle_pulmonaire","label":"Wikipedia — Hypertension artérielle pulmonaire"},{"href":"https://fr.wikipedia.org/wiki/Syndrome_d%27Eisenmenger","label":"Wikipedia — Syndrome d'Eisenmenger"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion d’endocardite infectieuse — Fièvre + cardiopathie à risque, souffle, accident embolique, purpura ou lombalgie — 1er temps systématique : 3 hémocultures (avant ATB) + ETT","detail":"<h4>CAT — suspicion d’<span class=\"kw-clinique\">endocardite</span> infectieuse — Démarche diagnostique : <span class=\"kw-bio\">hémocultures</span> + <span class=\"kw-imagerie\">échographie</span>, <span class=\"kw-def\">critères de</span> Duke 2023</h4>","branches":[{"to":"q-urgence","label":"Sepsis sévère, choc ou insuffisance cardiaque aiguë mal tolérée","color":"red"},{"to":"q-hemoc","label":"Patient stable → documenter avant de traiter","color":"green"}]},{"id":"q-urgence","kind":"decision","label":"Conduite en urgence — Traitement après les hémocultures, avant leur résultat","branches":[{"to":"t-atb-urg","label":"Forte suspicion (image écho) ou sepsis sévère","color":"red"},{"to":"t-chir-urg","label":"Indication chirurgicale urgente (IC réfractaire, infection non contrôlée)","color":"red"}]},{"id":"t-atb-urg","kind":"terminal","label":"Antibiothérapie probabiliste IV urgente","color":"red","detail":"<h4>Indication</h4><ul><li><span class=\"kw-alerte\">Forte suspicion</span> (image évocatrice à l’<span class=\"kw-imagerie\">écho</span>), <span class=\"kw-alerte\">sepsis sévère</span> ou <span class=\"kw-alerte\">indication chirurgicale urgente</span> — après <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span>, avant leur résultat.</li></ul><h4>Valve native ou prothèse &gt;<span class=\"kw-chiffre\"> 1 an</span></h4><ul><li><span class=\"kw-ttt\">Amoxicilline</span> + <span class=\"kw-ttt\">ceftriaxone</span> (ou <span class=\"kw-ttt\">oxacilline</span>) + <span class=\"kw-ttt\">gentamicine</span></li><li>Si <span class=\"kw-ci\">allergie aux pénicillines</span> : <span class=\"kw-ttt\">céfazoline</span> ou <span class=\"kw-ttt\">vancomycine</span> + <span class=\"kw-ttt\">gentamicine</span></li></ul><h4>Prothèse &lt;<span class=\"kw-chiffre\"> 1 an</span> ou EI non communautaire</h4><ul><li>Couvrir le <span class=\"kw-etio\">SARM</span> : <span class=\"kw-ttt\">vancomycine</span> (ou <span class=\"kw-ttt\">daptomycine</span>) + <span class=\"kw-ttt\">gentamicine</span> + <span class=\"kw-ttt\">rifampicine</span>.</li></ul><h4>Modalités</h4><ul><li><span class=\"kw-ttt\">Bactéricide</span>, synergique, <span class=\"kw-ttt\">IV</span>, <span class=\"kw-chiffre\">4 à 6 semaines</span> ; <span class=\"kw-ttt\">gentamicine</span> ≤ <span class=\"kw-chiffre\">15 jours</span> (<span class=\"kw-ci\">néphrotoxicité des aminosides</span>).</li></ul>"},{"id":"t-chir-urg","kind":"terminal","label":"Chirurgie cardiaque en phase active","color":"red","detail":"<h4>Hémodynamique</h4><ul><li><span class=\"kw-alerte\">Insuffisance cardiaque gauche réfractaire</span> ou <span class=\"kw-alerte\">choc cardiogénique</span></li><li><span class=\"kw-alerte\">Régurgitation aiguë</span> ou signe échographique de mauvaise tolérance</li></ul><h4>Infectieuse</h4><ul><li><span class=\"kw-alerte\">Infection non contrôlée localement</span> : <span class=\"kw-clinique\">abcès</span>, fistule, faux anévrisme, végétation croissante, désinsertion de prothèse, <span class=\"kw-alerte\">BAV</span></li><li>EI <span class=\"kw-etio\">fongique</span> ou à <span class=\"kw-etio\">germes multirésistants</span></li><li><span class=\"kw-bio\">Hémocultures</span> positives malgré <span class=\"kw-chiffre\">&gt; 7 jours</span> d’<span class=\"kw-ttt\">ATB</span></li></ul><h4><span class=\"kw-etio\">Embolique</span></h4><ul><li><span class=\"kw-clinique\">Végétation du cœur gauche</span> <span class=\"kw-chiffre\">&gt; 10 mm</span> persistante après embolie malgré ATB adaptée, ou associée à une autre indication chirurgicale.</li></ul><h4>Geste</h4><ul><li>Débridement des tissus infectés puis <span class=\"kw-ttt\">plastie</span> ou <span class=\"kw-ttt\">remplacement valvulaire</span>. <span class=\"kw-ci\">Imagerie cérébrale avant toute chirurgie</span> : une complication neurologique contre-indique temporairement la circulation extracorporelle.</li></ul>"},{"id":"q-hemoc","kind":"decision","label":"Hémocultures (positives dans 90 % des cas) — 3 prélèvements / 24 h, espacés ≥ 1 h, sur ponctions distinctes","branches":[{"to":"q-echo","label":"Positives à germe typique d’EI","color":"amber"},{"to":"t-hemoc-neg","label":"Négatives (≈ 10 % des EI)","color":"blue"}]},{"id":"q-echo","kind":"decision","label":"Échographie cardiaque : ETT puis ETO — ETO si ETT positive, ETT négative avec suspicion forte, ou matériel intracardiaque","branches":[{"to":"t-ei-certaine","label":"Lésion caractéristique d’EI (végétation, abcès, fistule…)","color":"amber"},{"to":"t-repeat","label":"Écho normale malgré suspicion forte","color":"blue"}]},{"id":"t-ei-certaine","kind":"terminal","label":"EI certaine (critères de Duke 2023)","color":"amber","detail":"<h4>Diagnostic</h4><ul><li>EI certaine si <span class=\"kw-chiffre\">2 critères majeurs</span>, ou <span class=\"kw-chiffre\">1 majeur + 3 mineurs</span>, ou <span class=\"kw-chiffre\">5 mineurs</span>. Majeurs = <span class=\"kw-bio\">hémocultures typiques</span> + <span class=\"kw-imagerie\">imagerie positive</span> (végétation, <span class=\"kw-clinique\">abcès</span>, fistule…).</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie documentée</span> : <span class=\"kw-ttt\">bactéricide</span>, synergique, <span class=\"kw-ttt\">IV</span>, <span class=\"kw-chiffre\">4 à 6 semaines</span>, adaptée au germe et à la valve</li><li><span class=\"kw-ttt\">Traitement de la porte d’entrée</span> indispensable (sinon récidive)</li><li>Discuter une <span class=\"kw-ttt\">chirurgie</span> selon <span class=\"kw-clinique\">les</span> indications hémodynamiques / infectieuses / emboliques</li></ul><h4>Bilan d’extension</h4><ul><li><span class=\"kw-imagerie\">TDM corps entier injectée</span> (localisations septiques, anévrismes mycotiques), <span class=\"kw-imagerie\">IRM cérébrale</span> sur point d’appel, <span class=\"kw-bio\">ECG</span> (recherche de <span class=\"kw-alerte\">BAV</span>).</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Régression <span class=\"kw-clinique\">fièvre</span> / <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">stérilisation des hémocultures</span>, <span class=\"kw-bio\">dosages</span> des <span class=\"kw-ttt\">aminosides</span>/<span class=\"kw-ttt\">vancomycine</span> ; guérison = <span class=\"kw-alerte\">absence de rechute</span> après arrêt.</li></ul>"},{"id":"t-repeat","kind":"terminal","label":"Écho normale : ne pas exclure l’EI","color":"blue","detail":"<h4>Conduite</h4><ul><li>Une <span class=\"kw-imagerie\">échographie normale n’élimine pas</span> le diagnostic : compléter par l’<span class=\"kw-imagerie\">ETO</span> (Se <span class=\"kw-chiffre\">≥ 90 %</span>) et répéter <span class=\"kw-imagerie\">ETT + ETO à J7-J10</span> si la suspicion persiste.</li></ul><h4>Imagerie de <span class=\"kw-chiffre\">2e ligne</span></h4><ul><li><span class=\"kw-imagerie\">TDM cardiaque</span> : <span class=\"kw-clinique\">abcès</span> non vus à l’écho (surtout sur prothèse)</li><li><span class=\"kw-imagerie\">TEP-scanner 18-FDG</span> ou <span class=\"kw-imagerie\">scintigraphie aux leucocytes marqués</span> (EI sur prothèse ; non interprétable <span class=\"kw-chiffre\">&lt; 3 mois</span> après <span class=\"kw-ttt\">chirurgie</span> valvulaire)</li></ul><h4>Microbiologie</h4><ul><li>Poursuivre <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">hémocultures</span> ; si elles restent stériles, dérouler la démarche « <span class=\"kw-bio\">hémocultures négatives</span> ».</li></ul>"},{"id":"t-hemoc-neg","kind":"terminal","label":"EI à hémocultures négatives","color":"blue","detail":"<h4>Causes</h4><ul><li><span class=\"kw-alerte\">ATB préalable</span> aux <span class=\"kw-bio\">hémocultures</span></li><li>Croissance lente : <span class=\"kw-etio\">streptocoques déficients</span>, <span class=\"kw-etio\">HACEK</span>, <span class=\"kw-etio\">Brucella</span>, <span class=\"kw-etio\">champignons</span></li><li>Intracellulaires : <span class=\"kw-etio\">Coxiella burnetii</span>, <span class=\"kw-etio\">Bartonella</span>, <span class=\"kw-etio\">Chlamydia</span>, <span class=\"kw-etio\">Tropheryma whipplei</span>, <span class=\"kw-etio\">Mycoplasma</span>, <span class=\"kw-etio\">Legionella</span></li></ul><h4>Conduite</h4><ul><li>Si <span class=\"kw-alerte\">ATB préalable</span> : <span class=\"kw-ttt\">interrompre</span>, attendre <span class=\"kw-chiffre\">≥ 72 h</span>, répéter <span class=\"kw-chiffre\">3 hémocultures</span> / <span class=\"kw-chiffre\">24 h</span> (sauf traitement urgent indispensable : végétation, <span class=\"kw-clinique\">abcès</span>, <span class=\"kw-alerte\">sepsis</span>)</li><li>Sinon : <span class=\"kw-bio\">techniques spéciales d’hémoculture</span>, <span class=\"kw-bio\">sérologies Coxiella / Bartonella</span>, <span class=\"kw-bio\">PCR</span></li><li>Si opéré : <span class=\"kw-bio\">histologie</span>, <span class=\"kw-bio\">culture</span> ± <span class=\"kw-bio\">PCR</span> de la pièce</li></ul><h4>Distracteurs</h4><ul><li>Ni la <span class=\"kw-etio\">maladie de Lyme</span> ni la <span class=\"kw-etio\">tuberculose</span> ne donnent d’<span class=\"kw-clinique\">endocardite</span>.</li></ul>"}]},"cards":[{"i":"123427253183","n":152,"o":"152-1","u":"Définition","t":"Connaître la définition d'une endocardite infectieuse (EI)","q":"Quelles structures cardiaques sont le plus souvent affectées par une endocardite infectieuse (EI) ?","a":"<p>L'endocardite infectieuse (EI) touche le plus souvent <strong>une ou plusieurs valves cardiaques natives</strong>. Elle peut aussi intéresser l'endocarde pariétal ou tout matériel intracardiaque implanté.</p>"},{"i":"16a0fb99d528","n":152,"o":"152-1","u":"Définition","t":"Connaître la définition d'une endocardite infectieuse (EI)","q":"Quelles valves cardiaques sont les plus fréquemment atteintes lors d'une endocardite infectieuse (EI) ?","a":"<p>Les valves du <strong>cœur gauche</strong> (mitrale, aortique) sont plus souvent touchées que celles du cœur droit.</p>"},{"i":"5affb602df53","n":152,"o":"152-1","u":"Définition","t":"Connaître la définition d'une endocardite infectieuse (EI)","q":"Quels sont les différents types de matériaux intracardiaques qui peuvent être infectés au cours d'une endocardite infectieuse (EI) ?","a":"<ul><li><strong>Prothèses valvulaires</strong></li><li>Sondes de stimulateur ou de défibrillateur</li><li>Assistances ventriculaires</li><li>Cathéters veineux centraux</li></ul>"},{"i":"fe482713c2e0","n":152,"o":"152-1","u":"Définition","t":"Connaître la définition d'une endocardite infectieuse (EI)","q":"Quelle est la définition d'une endocardite infectieuse (EI) ?","a":"<p>L'endocardite infectieuse (EI) est une <strong>infection de l'endocarde</strong>.</p>"}]};